DELETE FROM webhook_action_ledger WHERE event_id IN (SELECT id FROM webhook_event_ledger WHERE event_key = 'race_b7:expiry'); DELETE FROM webhook_event_ledger WHERE event_key = 'race_b7:expiry'; DO \$\$ DECLARE v_event UUID; v_token UUID; BEGIN SELECT event_id, lease_token INTO v_event, v_token FROM fn_webhook_claim_event('race_b7:expiry', 'comment', 999, '{}'::jsonb, 300); UPDATE webhook_event_ledger SET lease_expires_at = clock_timestamp() + interval '2 seconds' WHERE id = v_event; END \$\$;
